-- 94 Warehouse Robots: robots shuttle parcels from the aisles to the dock,
-- pathing round the racks - a tilemap the nav region bakes as walls - and
-- round crates, which are nav_obstacles: drag one into an aisle and they
-- replan. R swings the middle row's gate. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/94-warehouse-robots.scene"
local ROBOTS = 6
local CRATES = 4
local AISLES = { 300.0, 100.0, -100.0, -300.0 }
local DOCKS = { { 520.0, 220.0 }, { 520.0, 0.0 }, { 520.0, -220.0 } }
local X0, X1 = -540.0, 300.0
local GATE = { 12, 13 }
local GATE_ROWS = { 8, 9 }

local captions = true
local e = {}
local bots = {}
local crates = {}        -- id -> name
local dragged = nil
local gate_open = false
local t = 0
local rng = 94

local function rand()
    rng = (rng * 1103515245 + 12345) % 2147483648
    return rng / 2147483648
end

local function send(b, x, y)
    Nav.set_target(b.e, x, y)
    b.tx, b.ty = x, y
    b.sent = t
end

local function next_leg(b)
    if b.carrying then
        local d = DOCKS[math.floor(rand() * #DOCKS) + 1]
        send(b, d[1] + (rand() - 0.5) * 60, d[2] + (rand() - 0.5) * 60)
    else
        send(b, X0 + rand() * (X1 - X0), AISLES[math.floor(rand() * #AISLES) + 1])
    end
end

function init(entity)
    e.Racks = Entity.find_by_name("Racks")
    e.Cursor = Entity.find_by_name("Cursor")
    for i = 0, ROBOTS - 1 do
        bots[#bots + 1] = {
            e = Entity.find_by_name("Robot" .. i),
            parcel = Entity.find_by_name("Parcel" .. i),
            route = Entity.find_by_name("Route" .. i),
            carrying = false, sent = -1, tx = 0, ty = 0, route_t = rand() * 0.3,
        }
    end
    for i = 0, CRATES - 1 do
        local id = Entity.find_by_name("Crate" .. i)
        crates[id] = "Crate" .. i
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt

    -- R swings the gate in the middle rack row open or shut.
    if Input.is_key_just_pressed("R") then
        gate_open = not gate_open
        for c = GATE[1], GATE[2] do
            for _, r in ipairs(GATE_ROWS) do
                Tilemap.set_tile(e.Racks, "racks", c, r, gate_open and 0 or 1)
            end
        end
    end

    -- Each robot: to an aisle to pick a parcel up, then to the dock.
    for _, b in ipairs(bots) do
        if t - b.sent > 0.3 and not Nav.is_moving(b.e) then
            if b.sent >= 0 then b.carrying = not b.carrying end
            Sprite.set_color(b.parcel, 1, 1, 1, b.carrying and 1 or 0)
            next_leg(b)
        end
        b.route_t = b.route_t - dt
        if b.route_t <= 0 then
            b.route_t = 0.3
            local x, y = Transform.get_position(b.e)
            local path = Nav.find_path(x, y, b.tx, b.ty)
            if path then Line.set(b.route, "points", path) end
        end
    end

    -- Drag a crate with the mouse: a target joint toward the cursor.
    local mx, my = Input.get_mouse_world_position()
    Transform.set_position(e.Cursor, mx, my)
    if Input.is_mouse_left_just_pressed() then
        for _, id in ipairs(Physics.overlap_point(mx, my) or {}) do
            if crates[id] then
                dragged = crates[id]
                Physics.add_joint(dragged, "Cursor",
                    '{"target_entity":"Cursor","collide_connected":false,"joint_type":{"Target":{"frequency":4,"damping_ratio":0.8,"max_force":120000}}}')
                break
            end
        end
    end
    if dragged and not Input.is_mouse_left_pressed() then
        Physics.remove_joint(dragged)
        dragged = nil
    end
end
